{"command":"python3 -c '
import json
commands = []

# Bass pattern for pattern 1, channel 4 (0-indexed 3)
bass_notes = [
    (0,  24),  # C-1
    (8,  27),  # Eb-1
    (16, 29),  # F-1
    (24, 31),  # G-1
    (32, 24),  # C-1 again
    (40, 22),  # Bb0
    (48, 20),  # Ab0
    (56, 19),  # G0
]

for row, note in bass_notes:
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 1,
            "row": row,
            "channel": 3,
            "note": note,
            "instrument": 4,
            "volume": 48
        }
    })
    # Hold the note a bit
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 1,
            "row": row + 4,
            "channel": 3,
            "note": note + 128,  # key-off or continue
            "instrument": 0
        }
    })

# Add some variation in second half
for row, note in [(36, 24), (44, 27), (52, 29), (60, 24)]:
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 1,
            "row": row,
            "channel": 3,
            "note": note,
            "instrument": 4
        }
    })

print(json.dumps(commands))
' > /tmp/bass_pattern.json"}

